snippet_css:
:root{
  --bg: #FFFFFF;
  --fg: #101418;
  --muted: #5A6470;
  --surface: #F7F8FA;
  --border: #D5DAE0;
  --accent: #1A4FD6;
  --accent-fg: #FFFFFF;
  --radius: 3px;
  --radius-sm: 3px;
  --shadow: none;
  --btn-shadow: none;
  --art-bg: #F0F3F7;
  --media-bg: #F0F3F7;
  --cta-bg: #F7F8FA;
  --input-bg: #FFFFFF;
  --ok: #0E7A46;
  --warn: #B4232C;
  --font-display: Inter,'Noto Sans TC',sans-serif;
  --font-body: Inter,'Noto Sans TC',sans-serif;
  --font-mono: 'IBM Plex Mono',ui-monospace,monospace;
  --focus-ring: var(--accent);
}

snippet_tailwind:
// tailwind.config.js → theme.extend
{
  "colors": {
    "bg": "#FFFFFF",
    "fg": "#101418",
    "muted": "#5A6470",
    "surface": "#F7F8FA",
    "border": "#D5DAE0",
    "accent": "#1A4FD6",
    "accent-fg": "#FFFFFF",
    "ok": "#0E7A46",
    "warn": "#B4232C",
    "focus-ring": "var(--accent)"
  },
  "borderRadius": {
    "DEFAULT": "3px",
    "lg": "3px"
  },
  "fontFamily": {
    "display": [
      "Inter,'Noto Sans TC',sans-serif"
    ],
    "body": [
      "Inter,'Noto Sans TC',sans-serif"
    ]
  }
}
